      role2 = 102105,
      role3 = 102201,
      role5 = 1132402,
      sentence = "The freedom I'd waited so long for was at hand. All I needed to do was turn away, and I could leave this old mansion behind me forever.",
      next = {69}
    },
    [69] = {
