      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 1132000,
      role2 = 102101,
      role3 = 102201,
      role5 = 1132402,
      sentence = "I took a deep breath and walked up to Victor. He opened his slender eyes and regarded me with an inscrutable look.",
